"""Public tests for the 2020 LogLog midterm.
Passing them does not establish correctness or complexity."""
import math
import unittest
from unittest import mock
import loglog as q

FIGURE_L = ["aa", "ab", "a", "aa", "b", "a", "b", "aa", "ba", "ca", "a", "ab"]
# the 8-bit hash values of Figure 1 of the statement (the assignment to elements is arbitrary)
FIGURE_HASH = {"aa": "10110001", "ab": "11000101", "a": "11010010",
               "b": "00000010", "ba": "00101011", "ca": "11101001"}


def ref_sketch(L, b):
    """Independent reference built only from bin_hash."""
    A = [0] * 2 ** b
    for x in L:
        h = q.bin_hash(x)
        k = h[b:]
        z = len(k) - len(k.lstrip('0'))
        A[int(h[:b], 2)] = max(A[int(h[:b], 2)], 1 + z)
    return A


def ref_loglog(L, b):
    m = 2 ** b
    return q.constant(b) * m * m / sum(2.0 ** -s for s in ref_sketch(L, b))


class TestQ1(unittest.TestCase):
    def test_statement_example(self):
        self.assertEqual(q.cardinality(["aa", "ab", "a", "aa", "b", "ab"]), 4)

    def test_edges(self):
        self.assertEqual(q.cardinality([]), 0)
        self.assertEqual(q.cardinality(["x"] * 10), 1)
        self.assertEqual(q.cardinality(list(range(100)) * 3), 100)
        self.assertEqual(q.cardinality([1, 1.0, "1"]), 2)   # 1 == 1.0 in Python, "1" differs

    def test_input_untouched(self):
        L = ["b", "a", "b"]
        q.cardinality(L)
        self.assertEqual(L, ["b", "a", "b"])


class TestQ2(unittest.TestCase):
    def test_statement_example(self):
        self.assertEqual(q.bucket("1100010", 3), 6)
        self.assertEqual(q.zeros("1100010", 3), 2)

    def test_bucket(self):
        self.assertEqual(q.bucket("0000", 2), 0)
        self.assertEqual(q.bucket("1111", 2), 3)
        self.assertEqual(q.bucket("10", 1), 1)
        self.assertEqual(q.bucket("01101", 4), 6)

    def test_zeros(self):
        self.assertEqual(q.zeros("1110", 2), 0)        # bina[b] is '1'
        self.assertEqual(q.zeros("110000", 2), 4)      # all remaining symbols are '0'
        self.assertEqual(q.zeros("1101", 2), 1)        # suffix "01"
        self.assertEqual(q.zeros("0000100", 1), 3)
        self.assertEqual(q.zeros("00000000", 3), 5)


class TestQ3(unittest.TestCase):
    def test_figure_one(self):
        with mock.patch.object(q, "bin_hash", lambda x: FIGURE_HASH[x]):
            self.assertEqual(q.sketch(FIGURE_L, 2), [5, 0, 1, 4])

    def test_shape(self):
        self.assertEqual(q.sketch([], 3), [0] * 8)
        self.assertEqual(len(q.sketch(["a", "b", "c"], 4)), 16)

    def test_against_reference(self):
        for L, b in ((["a", "b", "c", "a"], 2), (list(range(40)), 3), (list(range(500)), 5)):
            self.assertEqual(q.sketch(L, b), ref_sketch(L, b))

    def test_repetitions_do_not_matter(self):
        L = list(range(30))
        self.assertEqual(q.sketch(L + L, 3), q.sketch(L, 3))


class TestQ4(unittest.TestCase):
    def test_formula(self):
        for L, b in ((list(range(1000)), 4), (list(range(5000)), 6), (["a", "b", "c"], 3)):
            self.assertAlmostEqual(q.loglog(L, b), ref_loglog(L, b), places=6)

    def test_all_buckets_size_one(self):
        # every bucket gets one hash whose zero-length is 0: s(i) = 1 for all i, so E = Const(2) * 8
        fake = lambda x: format(x, "02b") + "1" + "0" * 29
        with mock.patch.object(q, "bin_hash", fake):
            self.assertAlmostEqual(q.loglog([0, 1, 2, 3], 2), q.constant(2) * 8, places=9)

    def test_precision(self):
        n = 5000
        estimate = q.loglog(list(range(n)), 6)
        self.assertLess(abs(estimate - n) / n, 0.4)


class TestQ5(unittest.TestCase):
    def test_large_cardinality_is_unchanged(self):
        L = list(range(2000))
        self.assertAlmostEqual(q.loglog_small_range_correction(L, 4), q.loglog(L, 4), places=6)

    def test_small_cardinality_uses_empty_buckets(self):
        L, b = ["a", "b", "c"], 4
        m, empty = 2 ** b, ref_sketch(L, b).count(0)
        self.assertLessEqual(ref_loglog(L, b), 2.5 * m)
        self.assertGreater(empty, 0)
        self.assertAlmostEqual(q.loglog_small_range_correction(L, b), m * math.log(m / empty), places=9)

    def test_small_estimate_without_empty_bucket_returns_E(self):
        fake = lambda x: format(x, "02b") + "1" + "0" * 29
        with mock.patch.object(q, "bin_hash", fake):
            self.assertAlmostEqual(q.loglog_small_range_correction([0, 1, 2, 3], 2),
                                   q.constant(2) * 8, places=9)

    def test_empty_list(self):
        m = 2 ** 3
        self.assertAlmostEqual(q.loglog_small_range_correction([], 3), m * math.log(m / m), places=9)


if __name__ == '__main__':
    unittest.main(verbosity=2)
